import{b as o,O as t,g as a,j as l}from"./chunks/framework.DcaUmd3X.js";const _=JSON.parse('{"title":"人生海海","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/sea-of-life/index.md","filePath":"读书感悟/电子书架/40.人生海海.md","lastUpdated":1781614933000}'),c={name:"reading/digital/sea-of-life/index.md"};function r(p,e,i,d,n,u){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="人生海海" tabindex="-1">人生海海 <a class="header-anchor" href="#人生海海" aria-label="Permalink to &quot;人生海海&quot;">​</a></h1><p><code>麦家</code> <code>社会小说</code></p><h2 id="书摘" tabindex="-1">书摘 <a class="header-anchor" href="#书摘" aria-label="Permalink to &quot;书摘&quot;">​</a></h2><blockquote><p>📌 惊蛰不动土，春分不上山。清明吃青果，冬至吃白饼。立夏小满足，大雪兆丰年。鲤鱼跳龙门，雷公进屋门。朝霞不出门，晚霞行千里。</p></blockquote><blockquote><p>📌 心有雷霆面若静湖</p></blockquote><blockquote><p>📌 世上只有一种英雄主义，就是在认清了生活真相后依然热爱生活</p></blockquote><blockquote><p>📌 形容人生复杂多变但又不止这意思，它的意思像大海一样宽广，但总的说是教人好好活而不是去死的意思。</p></blockquote><blockquote><p>📌 记住，人生海海，敢死不叫勇气，活着才需要勇气</p></blockquote><blockquote><p>📌 报纸上说，没有完美的人生，不完美才是人生。我哭着，想着，不知道我的哭声能传到多远，能唤来多少阴阳两界的灵和人为他们送行？</p></blockquote><h2 id="书评" tabindex="-1">书评 <a class="header-anchor" href="#书评" aria-label="Permalink to &quot;书评&quot;">​</a></h2><blockquote><p>💭 泪目</p><p>📌 村里出动几百人，男女老少，成群结队，送他们到富春江边，船埠头。船在汽笛声中离开码头，女人对着送行的村民长跪不起，抹着泪，上校像孩子随母亲一样，跟着跪下来，那情景把几百人都感动哭了。几百人哭的场面能感动所有人和所有时间，父亲在回忆中依然禁不住滚出泪花。</p></blockquote><blockquote><p>💭 其实是你自己说的，只不过说报纸上会更有信服力</p><p>📌 报纸上说，生活是如此令人绝望，但人们兴高采烈地活着。</p></blockquote>',12)])])}const b=o(c,[["render",r]]);export{_ as __pageData,b as default};
